module mips_controller ( opcode, reg_dst, jump, branch, mem_rd, mem_wrt, 
        alu_op, mem2reg, alu_src, reg_write, and_data2alu, bne );
  input [5:0] opcode;
  output [1:0] alu_op;
  output reg_dst, jump, branch, mem_rd, mem_wrt, mem2reg, alu_src, reg_write,
         and_data2alu, bne;
  wire   mem_rd, n3, n4, n5, n6, n7, n8, n9, n10, n11, n1, n2;
  assign mem2reg = mem_rd;

  AO21X1 U8 ( .IN1(n3), .IN2(n4), .IN3(mem_rd), .Q(reg_write) );
  AND3X1 U9 ( .IN1(opcode[3]), .IN2(n5), .IN3(n6), .Q(mem_wrt) );
  AND3X1 U10 ( .IN1(n5), .IN2(n2), .IN3(n6), .Q(mem_rd) );
  NOR4X0 U11 ( .IN1(n7), .IN2(opcode[0]), .IN3(opcode[5]), .IN4(opcode[3]), 
        .QN(jump) );
  AND2X1 U12 ( .IN1(opcode[0]), .IN2(alu_op[0]), .Q(bne) );
  OA21X1 U13 ( .IN1(n8), .IN2(n5), .IN3(n6), .Q(alu_src) );
  AND2X1 U14 ( .IN1(n9), .IN2(n10), .Q(n5) );
  NOR3X0 U15 ( .IN1(n2), .IN2(n10), .IN3(n9), .QN(n8) );
  OR2X1 U16 ( .IN1(reg_dst), .IN2(and_data2alu), .Q(alu_op[1]) );
  AND3X1 U17 ( .IN1(n3), .IN2(opcode[2]), .IN3(opcode[3]), .Q(and_data2alu) );
  NOR3X0 U18 ( .IN1(opcode[2]), .IN2(opcode[3]), .IN3(n1), .QN(reg_dst) );
  NOR3X0 U19 ( .IN1(n9), .IN2(opcode[4]), .IN3(n10), .QN(n3) );
  AO22X1 U20 ( .IN1(opcode[0]), .IN2(opcode[1]), .IN3(opcode[5]), .IN4(n11), 
        .Q(n10) );
  XOR2X1 U21 ( .IN1(opcode[5]), .IN2(n11), .Q(n9) );
  XOR2X1 U22 ( .IN1(opcode[0]), .IN2(opcode[1]), .Q(n11) );
  NOR4X0 U23 ( .IN1(n4), .IN2(opcode[1]), .IN3(opcode[4]), .IN4(opcode[5]), 
        .QN(alu_op[0]) );
  NOR2X0 U2 ( .IN1(n1), .IN2(n4), .QN(branch) );
  INVX0 U3 ( .INP(n3), .ZN(n1) );
  NOR2X0 U4 ( .IN1(opcode[2]), .IN2(opcode[4]), .QN(n6) );
  INVX0 U5 ( .INP(opcode[3]), .ZN(n2) );
  NAND2X1 U6 ( .IN1(opcode[2]), .IN2(n2), .QN(n4) );
  NAND2X1 U7 ( .IN1(n6), .IN2(opcode[1]), .QN(n7) );
endmodule


module alu_ctrl ( alu_op, func, alu_ctrl, jr, shift_ren, shift_len, 
        shift_data2reg );
  input [1:0] alu_op;
  input [5:0] func;
  output [3:0] alu_ctrl;
  output jr, shift_ren, shift_len, shift_data2reg;
  wire   n12, n13, n14, n15, n16, n17, n18, n19, n20, n21, n22, n23, n1, n3,
         n4, n5, n6, n7, n8, n9, n10, n11;
  assign alu_ctrl[3] = 1'b0;

  NAND4X0 U20 ( .IN1(n4), .IN2(n11), .IN3(alu_op[1]), .IN4(n13), .QN(n12) );
  NOR4X0 U21 ( .IN1(func[5]), .IN2(func[4]), .IN3(func[3]), .IN4(func[2]), 
        .QN(n13) );
  NOR4X0 U22 ( .IN1(n14), .IN2(n15), .IN3(func[0]), .IN4(n8), .QN(jr) );
  NAND3X0 U23 ( .IN1(n9), .IN2(n5), .IN3(n10), .QN(n14) );
  AO22X1 U24 ( .IN1(alu_op[0]), .IN2(n1), .IN3(n3), .IN4(n16), .Q(alu_ctrl[2])
         );
  OAI21X1 U25 ( .IN1(n17), .IN2(n10), .IN3(n18), .QN(n16) );
  NAND3X0 U26 ( .IN1(n4), .IN2(n7), .IN3(n20), .QN(n19) );
  NAND4X0 U27 ( .IN1(func[5]), .IN2(n11), .IN3(n9), .IN4(n8), .QN(n17) );
  OA21X1 U28 ( .IN1(n21), .IN2(n6), .IN3(n3), .Q(alu_ctrl[0]) );
  NAND3X0 U29 ( .IN1(n4), .IN2(n7), .IN3(alu_op[1]), .QN(n15) );
  NAND4X0 U30 ( .IN1(func[1]), .IN2(func[3]), .IN3(n22), .IN4(func[5]), .QN(
        n18) );
  NOR4X0 U31 ( .IN1(n23), .IN2(n5), .IN3(func[3]), .IN4(func[1]), .QN(n21) );
  INVX0 U3 ( .INP(n15), .ZN(n3) );
  INVX0 U4 ( .INP(alu_op[1]), .ZN(n1) );
  INVX0 U5 ( .INP(alu_op[0]), .ZN(n4) );
  NAND2X1 U6 ( .IN1(alu_op[1]), .IN2(n19), .QN(alu_ctrl[1]) );
  NAND2X1 U7 ( .IN1(n18), .IN2(n17), .QN(n20) );
  INVX0 U8 ( .INP(n12), .ZN(shift_data2reg) );
  NOR2X0 U9 ( .IN1(n12), .IN2(n10), .QN(shift_ren) );
  NOR2X0 U10 ( .IN1(func[2]), .IN2(func[0]), .QN(n22) );
  INVX0 U11 ( .INP(n18), .ZN(n6) );
  NAND2X1 U12 ( .IN1(func[0]), .IN2(func[2]), .QN(n23) );
  INVX0 U13 ( .INP(func[1]), .ZN(n10) );
  INVX0 U14 ( .INP(func[5]), .ZN(n5) );
  INVX0 U15 ( .INP(func[4]), .ZN(n7) );
  INVX0 U16 ( .INP(func[3]), .ZN(n8) );
  INVX0 U17 ( .INP(func[2]), .ZN(n9) );
  INVX0 U18 ( .INP(func[0]), .ZN(n11) );
  NOR2X0 U19 ( .IN1(func[1]), .IN2(n12), .QN(shift_len) );
endmodule


module mips_cpu_top ( clock, reset, PC, Inst, MemRead, MemWrite, Addr, Din, 
        Dout );
  output [31:0] PC;
  input [31:0] Inst;
  output [31:0] Addr;
  output [31:0] Din;
  input [31:0] Dout;
  input clock, reset;
  output MemRead, MemWrite;
  wire   w_reg_dst, w_jmp, w_jmp_reg, w_branch, w_mem2reg, w_alu_src,
         w_reg_write, w_shift_ren, w_shift_len, w_shift_data2reg,
         w_and_data2alu, w_bne;
  wire   [3:0] w_alu_ctrl;
  wire   [1:0] w_alu_op;
  wire   SYNOPSYS_UNCONNECTED__0;

  mips_datapath dat_path_inst ( .reg_dst(w_reg_dst), .jump(w_jmp), .jr(
        w_jmp_reg), .branch(w_branch), .bne(w_bne), .inst(Inst), .mem2reg(
        w_mem2reg), .alu_src(w_alu_src), .alu_ctrl({1'b0, w_alu_ctrl[2:0]}), 
        .clk(clock), .reset(reset), .reg_wrt(w_reg_write), .mem_data(Dout), 
        .pc(PC), .shift_ren(w_shift_ren), .shift_len(w_shift_len), 
        .shift_data2reg(w_shift_data2reg), .and_data2alu(w_and_data2alu), 
        .data_mem_addr(Addr), .sw_data(Din) );
  mips_controller ctrl_inst ( .opcode(Inst[31:26]), .reg_dst(w_reg_dst), 
        .jump(w_jmp), .branch(w_branch), .mem_rd(MemRead), .mem_wrt(MemWrite), 
        .alu_op(w_alu_op), .mem2reg(w_mem2reg), .alu_src(w_alu_src), 
        .reg_write(w_reg_write), .and_data2alu(w_and_data2alu), .bne(w_bne) );
  alu_ctrl alu_ctrl_inst ( .alu_op(w_alu_op), .func(Inst[5:0]), .alu_ctrl({
        SYNOPSYS_UNCONNECTED__0, w_alu_ctrl[2:0]}), .jr(w_jmp_reg), 
        .shift_ren(w_shift_ren), .shift_len(w_shift_len), .shift_data2reg(
        w_shift_data2reg) );
endmodule

